import Foundation

/// Offline checks (no network). Runs from the CLI and the iOS app; returns failure messages.
public enum SelfTest {
    public static func run() -> [String] {
        var failures: [String] = []
        func check(_ ok: Bool, _ message: String) { if !ok { failures.append(message) } }

        // Expected values generated by fli 881aee5 `encode_tfs_payload(encode_tfs_segment(...))`.
        let tfsCases = [
            ("CGK", "DPS", "2026-12-15", "CBwQAhoeEgoyMDI2LTEyLTE1agcIARIDQ0dLcgcIARIDRFBTQAFIAXABmAEC"),
            ("SIN", "NRT", "2027-01-03", "CBwQAhoeEgoyMDI3LTAxLTAzagcIARIDU0lOcgcIARIDTlJUQAFIAXABmAEC"),
            ("JFK", "LHR", "2026-11-30", "CBwQAhoeEgoyMDI2LTExLTMwagcIARIDSkZLcgcIARIDTEhSQAFIAXABmAEC"),
        ]
        for (o, d, date, expected) in tfsCases {
            let got = Tfs.encode(origin: o, destination: d, date: date)
            check(got == expected, "tfs \(o)-\(d) \(date): \(got)")
        }

        // fli `extract_currency_from_price_token("GgUaA0lEUg") == "IDR"`.
        check(Page.currency(fromToken: "GgUaA0lEUg") == "IDR", "currency token")
        check(Page.currency(fromToken: "!!") == nil, "bad currency token")

        // Synthetic page (hand-built, not a provider payload) with the decoder's index layout.
        func leg(_ o: String, _ d: String, _ flight: String) -> [Any] {
            var fl = [Any](repeating: NSNull(), count: 23)
            fl[3] = o; fl[6] = d
            fl[8] = [6, 5]; fl[10] = [9, NSNull()]; fl[11] = 115
            fl[20] = [2026, 12, 15]; fl[21] = [2026, 12, 15]
            fl[22] = ["GA", flight, NSNull()]
            return fl
        }
        func detail(_ legs: [[Any]]) -> [Any] {
            var d = [Any](repeating: NSNull(), count: 10)
            d[2] = legs; d[9] = 115
            return d
        }
        let priced: [Any] = [detail([leg("CGK", "DPS", "402")]), [[NSNull(), 1_250_000], "GgUaA0lEUg"]]
        let fractional: [Any] = [detail([leg("CGK", "SUB", "300"), leg("SUB", "DPS", "344")]), [[NSNull(), 1234.5], "GgUaA0lEUg"]]
        let unpriced: [Any] = [detail([leg("CGK", "DPS", "404")]), [[], "GgUaA0lEUg"]]
        let payload: [Any] = [NSNull(), NSNull(), [[priced, fractional, unpriced]], NSNull()]
        let json = String(decoding: try! JSONSerialization.data(withJSONObject: payload), as: UTF8.self)
        let html = "<script>AF_initDataCallback({key: 'ds:0', hash: '1', data:[1], sideChannel: {}});</script>"
            + "<script>AF_initDataCallback({key: 'ds:1', hash: '2', data:\(json), sideChannel: {}});</script>"

        if let extracted = Page.extractDs1(html), let decoded = try? Page.decode(extracted) {
            check(decoded.offers.count == 2 && decoded.unpriced == 1, "offer/unpriced counts")
            let first = decoded.offers[0]
            check(first.price == Decimal(1_250_000) && first.currency == "IDR", "integral price \(first.priceText)")
            check(first.legs.first?.departLocal == "2026-12-15T06:05", "depart time")
            check(first.legs.first?.arriveLocal == "2026-12-15T09:00", "arrive time with null minute")
            check(decoded.offers[1].price == Decimal(string: "1234.5"), "fractional price \(decoded.offers[1].priceText)")
            check(decoded.offers[1].legs.map(\.flightNumber) == ["300", "344"], "connection legs")
            check(FliProbe.crossCheck(decoded, origin: "CGK", destination: "DPS", date: "2026-12-15", currency: "IDR") == nil,
                  "cross-check should pass")
            check(FliProbe.crossCheck(decoded, origin: "CGK", destination: "DPS", date: "2026-12-16", currency: "IDR") != nil,
                  "cross-check should catch wrong date")
        } else {
            failures.append("synthetic page did not extract/decode")
        }
        check(Page.extractDs1("<html>no data</html>") == nil, "row-less page")
        check((try? Page.decode([NSNull(), NSNull(), NSNull(), NSNull()])) == nil, "no row groups must fail")
        check(Page.isTrafficBlock("Our systems have detected unusual traffic"), "traffic marker")

        // Redirect policy from providers/fli.py.
        check(isAllowedRedirect(URL(string: "https://www.google.com/travel/flights?tfs=x")!), "allow same path")
        check(!isAllowedRedirect(URL(string: "https://www.google.com/sorry/index?continue=x")!), "block /sorry")
        check(!isAllowedRedirect(URL(string: "https://consent.google.com/m?x")!), "block consent")
        check(!isAllowedRedirect(URL(string: "https://www.google.com/travel/flights/unsupported")!), "block unsupported")
        check(!isAllowedRedirect(URL(string: "http://www.google.com/travel/flights")!), "block http")
        return failures
    }
}
